settings.custom_liquid:
{% if collection.description != blank %}
  <!-- Collection Description Popup Widget - Simple Version -->
  <div class="collection-popup-widget">
    <!-- Trigger Button -->
    <button class="collection-popup-btn" onclick="openCollectionModal()">
      LEARN ABOUT {{ collection.title | upcase }}
    </button>

    <!-- Modal Overlay -->
    <div class="collection-modal-overlay" id="collectionModalOverlay" onclick="closeCollectionModal()">
      <div class="collection-modal" onclick="event.stopPropagation()">
        <!-- Close Button -->
        <button class="modal-close" onclick="closeCollectionModal()">
          ✕
        </button>

        <!-- Modal Content -->
        <div class="modal-content">
          <!-- Header -->
          <div class="modal-header">
            <h2 class="modal-title">DISCOVER OUR {{ collection.title | upcase }}</h2>
            <p class="modal-subtitle">{{ collection.metafields.custom.subtitle | default: 'EXPLORE OUR CURATED COLLECTION' }}</p>
          </div>

          <!-- Description Content -->
          <div class="modal-body">
            <div class="collection-description">
              {{ collection.description }}
            </div>
          </div>

          <!-- Action Button -->
          <div class="modal-actions">
            <button class="continue-btn" onclick="closeCollectionModal()">
              CONTINUE SHOPPING
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- Styles -->
  <style>
    .collection-popup-widget {
      margin: 20px 20px;
    display: flex;
    justify-content: center;
    }

    .collection-popup-btn {
      background: #000;
      color: #fff;
      border: none;
      padding: 15px 30px;
      font-family: Arial, sans-serif;
      font-size: 14px;
      font-weight: bold;
      letter-spacing: 1px;
      cursor: pointer;
      transition: background 0.3s ease;
      text-transform: uppercase;
    }

    .collection-popup-btn:hover {
      background: #333;
    }

    .collection-modal-overlay {
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background: rgba(0, 0, 0, 0.8);
      z-index: 9999;
      display: flex;
      align-items: center;
      justify-content: center;
      opacity: 0;
      visibility: hidden;
      transition: all 0.3s ease;
    }

    .collection-modal-overlay.active {
      opacity: 1;
      visibility: visible;
    }

    .collection-modal {
      background: #fff;
      width: 90%;
      max-width: 600px;
      max-height: 80vh;
      position: relative;
      transform: scale(0.9);
      transition: transform 0.3s ease;
      overflow: hidden;
    }

    .collection-modal-overlay.active .collection-modal {
      transform: scale(1);
    }

    .modal-close {
      position: absolute;
      top: 15px;
      right: 15px;
      background: #000;
      color: #fff;
      border: none;
      width: 30px;
      height: 30px;
      font-size: 16px;
      cursor: pointer;
      z-index: 10;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .modal-close:hover {
      background: #333;
    }

    .modal-content {
      padding: 40px;
      overflow-y: auto;
      max-height: 80vh;
    }

    .modal-header {
      text-align: center;
      margin-bottom: 30px;
    }

    .modal-title {
      font-family: Arial, sans-serif;
      font-size: 28px;
      font-weight: bold;
      color: #000;
      margin: 0 0 15px 0;
      letter-spacing: 0.5px;
      text-transform: uppercase;
      line-height: 1.2;
    }

    .modal-subtitle {
      font-family: Arial, sans-serif;
      font-size: 14px;
      color: #666;
      margin: 0;
      letter-spacing: 0.5px;
      text-transform: uppercase;
    }

    .modal-body {
      margin-bottom: 40px;
    }

    .collection-description {
      font-family: Arial, sans-serif;
      font-size: 16px;
      line-height: 1.6;
      color: #333;
      text-align: center;
    }

    .collection-description p {
      margin-bottom: 15px;
    }

    .collection-description h1,
    .collection-description h2,
    .collection-description h3,
    .collection-description h4,
    .collection-description h5,
    .collection-description h6 {
      font-weight: bold;
      margin: 20px 0 10px 0;
      color: #000;
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }

    .modal-actions {
      text-align: center;
    }

    .continue-btn {
      background: #000;
      color: #fff;
      border: none;
      padding: 15px;
      font-family: Arial, sans-serif;
      font-size: 14px;
      font-weight: bold;
      letter-spacing: 1px;
      text-transform: uppercase;
      cursor: pointer;
      transition: background 0.3s ease;
      width: 100%;
    }

    .continue-btn:hover {
      background: #333;
    }

    @media (max-width: 768px) {
      .modal-content {
        padding: 30px 20px;
      }

      .modal-title {
        font-size: 24px;
      }

      .collection-description {
        font-size: 15px;
      }
    }

    @media (max-width: 480px) {
      .collection-modal {
        width: 95%;
        margin: 20px;
      }

      .modal-content {
        padding: 25px 15px;
      }

      .modal-title {
        font-size: 20px;
      }

      .collection-description {
        font-size: 14px;
      }

      .continue-btn {
        padding: 12px 30px;
        font-size: 13px;
      }
    }
  </style>

  <!-- JavaScript -->
  <script>
    function openCollectionModal() {
      const overlay = document.getElementById('collectionModalOverlay');
      overlay.classList.add('active');
      document.body.style.overflow = 'hidden';
    }

    function closeCollectionModal() {
      const overlay = document.getElementById('collectionModalOverlay');
      overlay.classList.remove('active');
      document.body.style.overflow = '';
    }

    document.addEventListener('keydown', function(event) {
      if (event.key === 'Escape') {
        closeCollectionModal();
      }
    });
  </script>
{% endif %}
